-- ============================================================================
-- ZANKA LEDGER MODULE — PHASE 1 (revised — unique keys)
-- 007_staging_legacy_transactions.sql
--
-- Your spreadsheet's own Posting ID column has 3 duplicate values
-- (J-0042-001, J-0042-002, J-0051-007 each used twice for different rows —
-- a data-entry slip in the spreadsheet, not something introduced here).
-- row_seq is a synthetic guaranteed-unique key (R0001, R0002, ...); the
-- original posting_id is kept as a plain column for traceability, just not
-- as the primary key.
--
-- 4 journal pairs that didn't balance individually (J-0008/09, J-0028/29,
-- J-0040/43, J-0041/42) are merged into one journal_number each, per your
-- confirmation that each pair is one transaction split across two numbers.
-- ============================================================================

create table if not exists public.stg_legacy_transactions (
  row_seq        text primary key,
  posting_id     text not null,
  journal_number text not null,
  entry_date     date not null,
  property_code  text,
  tenant_code    text,
  lease_code     text,
  account_code   integer not null,
  dr_cr          text not null,
  amount         numeric(14,2) not null,
  description    text,
  ref_code       text,
  tax_treatment  text,
  tax_group      text,
  imported       boolean not null default false
);

create index if not exists idx_stg_legacy_posting_id on public.stg_legacy_transactions(posting_id);
create index if not exists idx_stg_legacy_journal_number on public.stg_legacy_transactions(journal_number);

